/* Loading: built-in window.RT_DATA + ad-hoc FileReader (global script).
   No fetch/XHR local reads (decision B). */

interface Window { RT_DATA?: RtData; }

/** Built-in bundle generated by viewer/tools/embed.py (may be absent). */
function builtinData(): RtData | null {
  if (typeof window === "undefined") return null;
  return window.RT_DATA ?? null;
}

/** Read a JSON file object chosen via <input type="file">. */
function readJsonFile(file: File): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("파일 읽기 실패"));
    reader.onload = () => {
      try {
        resolve(JSON.parse(String(reader.result)) as unknown);
      } catch (e) {
        reject(new Error("JSON 파싱 실패: " + String(e)));
      }
    };
    reader.readAsText(file);
  });
}

/** Load an ad-hoc run log chosen via <input type="file">. */
function loadLogFile(file: File): Promise<RunLog> {
  return readJsonFile(file).then((doc) => {
    const bad = validateLogForPlayback(doc);
    if (bad) throw new Error(bad);
    return doc as RunLog;
  });
}

/** Load an ad-hoc puzzle.json chosen via <input type="file">. */
function loadPuzzleFile(file: File): Promise<FilePuzzleData> {
  return readJsonFile(file).then((doc) => doc as FilePuzzleData);
}

/** Sample-set id linked by viewer/testdata/failed.json (T040/T046). */
const FAILED_SAMPLE_SET_ID = "viewer-failed";
/** Sample-set id linked by viewer/testdata/multilayer.json (T041/T047). */
const MULTILAYER_SAMPLE_SET_ID = "viewer-multilayer";

/** One sample-set bundle embedded in window.RT_DATA (viewer/testdata/sets/<id>/). */
function sampleSetFor(data: RtData | null, setId: string): SampleSetBundle | null {
  if (!data || !data.sample_sets) return null;
  return data.sample_sets[setId] ?? null;
}

/** Space + puzzle of one embedded sample set (both must be present). */
function sampleStaticFor(data: RtData | null, setId: string): { space: SpaceData; puzzle: PuzzleData } | null {
  const set = sampleSetFor(data, setId);
  if (set && set.space && set.puzzle) {
    return { space: set.space, puzzle: set.puzzle };
  }
  return null;
}

/** T044: static data of the failed.json sample set from built-in RT_DATA. */
function failedSampleStatic(data: RtData | null): { space: SpaceData; puzzle: PuzzleData } | null {
  return sampleStaticFor(data, FAILED_SAMPLE_SET_ID);
}

/** T045: static data of the multilayer.json sample set from built-in RT_DATA. */
function multilayerSampleStatic(data: RtData | null): { space: SpaceData; puzzle: PuzzleData } | null {
  return sampleStaticFor(data, MULTILAYER_SAMPLE_SET_ID);
}

/** Reveals entry of one embedded sample-set log (keys like "testdata/failed"). */
function sampleRevealsFor(data: RtData | null, setId: string, logKey: string): { [puzzleNumber: string]: RevealEntry } | null {
  const set = sampleSetFor(data, setId);
  if (set && set.reveals && set.reveals[logKey]) {
    return set.reveals[logKey];
  }
  return null;
}

/** T044: reveals of testdata/failed from built-in RT_DATA. */
function failedSampleReveals(data: RtData | null): { [puzzleNumber: string]: RevealEntry } | null {
  return sampleRevealsFor(data, FAILED_SAMPLE_SET_ID, "testdata/failed");
}

/** T045: reveals of testdata/multilayer from built-in RT_DATA. */
function multilayerSampleReveals(data: RtData | null): { [puzzleNumber: string]: RevealEntry } | null {
  return sampleRevealsFor(data, MULTILAYER_SAMPLE_SET_ID, "testdata/multilayer");
}
